`timescale 1ns/1ps
// Basys 3 top level - generated by scripts/make_experiments.py
module top_basys3 (
    input  wire        clk,                    // 100 MHz
    input  wire        btnC, btnU, btnL, btnR, // btnC = reset
    input  wire [15:0] sw,
    output wire [15:0] led,
    output wire [3:0]  an,
    output wire [6:0]  seg
);
    wire rst = btnC;
    wire en;   // one model step every 1/25 s, slow enough to watch
    step_tick #(.STEP_HZ(25)) u_tick (.clk(clk), .rst(rst), .tick(en));
    wire pre, post;
    btn_pulse u_bl (.clk(clk), .rst(rst), .tick(en), .btn(btnL), .pulse(pre));    // btnL = pre spike
    btn_pulse u_br (.clk(clk), .rst(rst), .tick(en), .btn(btnR), .pulse(post));   // btnR = post spike
    wire signed [31:0] w, xp, xq;
    stdp_synapse u_s (.clk(clk), .rst(rst), .en(en), .pre_spike(pre), .post_spike(post), .learn(1'b1), .w(w), .x_pre(xp), .x_post(xq));
    wire spike_led;
    pulse_stretch u_ps (.clk(clk), .rst(rst), .in(pre | post), .out(spike_led));
    wire signed [31:0] bar_val = w;
    bar15 #(.FULL(255)) u_bar (.val(bar_val), .leds(led[14:0]));
    assign led[15] = spike_led;
    wire signed [31:0] num = w;
    seg7_signed u_seg (.clk(clk), .value(num[15:0]), .an(an), .seg(seg));
endmodule
